        {"into": "cleaner_type_value", "candidates": ["cleaner_type_value"]}
      ]
    }
  ],
  "compute": [
    {"prim": "first", "args": ["$product_rows"], "into": "product_row"},
    {"prim": "get", "args": ["$product_row", "product_sku"], "into": "product_sku"},
    {"prim": "get", "args": ["$product_row", "record_path"], "into": "product_record_path"},
    {"prim": "get", "args": ["$product_row", "cleaner_type_value"], "into": "cleaner_type_value"}
  ],
  "decision": {
    "branches": [
      {
        "when": {
          "op": "and",
          "args": [
            {"op": "nonempty", "lhs": "$product_sku", "rhs": null},
            {"op": "contains_any", "lhs": "$cleaner_type_value", "rhs": ["multi surface cleaner"]},
            {"op": "contains_any", "lhs": "$cleaner_type_value", "rhs": ["floor cleaner"]}
          ]
        },
        "label": "both_present"
      },
      {
        "when": {
          "op": "and",
          "args": [
            {"op": "nonempty", "lhs": "$product_sku", "rhs": null},
